cases.definition_yaml:
name: jira-defect-loop
description: Process one immutable bounded Jira defect manifest through approved GitLab fixes
tags: [ericsson, jira, gitlab, batch]
requires: [ericsson-jira, ericsson-gitlab]
nodes:
  - id: fetch-ticket-manifest
    prompt: >
      Call jira_my_tickets exactly one time with {"max_results": 25}. Do not
      retry, page, refresh, or make a second manifest call. Preserve first
      occurrence order, deduplicate exact Jira keys, and return at most 25
      keys. This is the immutable run manifest; later tickets wait for the
      next run. Return empty status only for an empty corroborated result.
    allowed_tools: [jira_my_tickets]
    tool_call_contract:
      name: jira_my_tickets
      arguments: {max_results: 25}
      result:
        items_path: result.items
        select: [key]
        output_items_path: tickets
        output_count_path: count
        output_status_path: status
        empty_status: empty
        nonempty_status: ready
        max_items: 25
    maxTurns: 2
    retry: {max_attempts: 0}
    output_format:
      type: object
      additionalProperties: false
      required: [status, count, tickets, warnings]
      properties:
        status: {type: string, enum: [ready, empty]}
        count: {type: integer, minimum: 0, maximum: 25}
        tickets:
          type: array
          maxItems: 25
          uniqueItems: true
          items:
            type: object
            additionalProperties: false
            required: [key]
            properties:
              key: {type: string, minLength: 1, maxLength: 128, pattern: '^[A-Za-z][A-Za-z0-9_]*-[0-9]+$'}
        warnings: {type: array, maxItems: 25, items: {type: string, maxLength: 1024}}

  - id: process-ticket-manifest
    depends_on: [fetch-ticket-manifest]
    when: "$fetch-ticket-manifest.output.count > 0"
    loop_group:
      until: BATCH_COMPLETE
      max_iterations: 25
      fresh_context: true
      nodes:
        - id: select-ticket
          script: |
            const manifest = $fetch-ticket-manifest.output;
            const previous = [$LOOP_PREV.record-cumulative-state.output];
            const prior = previous.length ? previous[0] : {completed_count: 0, records: []};
            if (!Array.isArray(manifest.tickets) || manifest.tickets.length !== manifest.count || manifest.count > 25) throw new Error("invalid immutable manifest");
            const keys = manifest.tickets.map((ticket) => ticket.key);
            if (new Set(keys).size !== keys.length) throw new Error("duplicate immutable manifest key");
            if (!Array.isArray(prior.records) || prior.completed_count !== prior.records.length) throw new Error("invalid cumulative state");
            const completed = prior.records.map((record) => record.ticket_key);
            if (JSON.stringify(completed) !== JSON.stringify(keys.slice(0, completed.length))) throw new Error("cumulative state is outside manifest order");
            if (completed.length >= keys.length) throw new Error("no remaining manifest key");
            console.log(JSON.stringify({ticket_key: keys[completed.length], manifest_count: keys.length, index: completed.length}));
          runtime: bun
          artifacts: false
          output_format:
            type: object
            additionalProperties: false
            required: [ticket_key, manifest_count, index]
            properties:
              ticket_key: {type: string, minLength: 1, maxLength: 128}
              manifest_count: {type: integer, minimum: 1, maximum: 25}
              index: {type: integer, minimum: 0, maximum: 24}

        - id: prepare-writes
          depends_on: [select-ticket]
          prompt: >
            Process only immutable manifest ticket $select-ticket.output.ticket_key
            at index $select-ticket.output.index of
            $select-ticket.output.manifest_count; call jira_get_issue once for
            that key. For a corroborated code fix, use only the bounded GitLab
            read tools. Prepare, but do not execute, exact connector argument
            objects for each possible write. Preserve every action content byte
            and any current last_commit_id. Compute an intent digest for each
            exact argument object. Set a should flag to zero unless its payload
            is complete and corroborated. Triage confidence is not authority.
          allowed_tools: [jira_get_issue, gitlab_resolve_project, gitlab_list_repository_tree, gitlab_read_file]
          retry: {max_attempts: 1}
          output_format:
            type: object
            additionalProperties: false
            required: [ticket_key, manifest_count, project_path, branch_name, branch_args, commit_args, merge_request_args, jira_comment_args, should_create_branch, should_commit, should_create_merge_request, should_comment_jira, branch_intent_digest, commit_intent_digest, merge_request_intent_digest, jira_comment_intent_digest, terminal_outcome, warnings]
            properties:
              ticket_key: {type: string, minLength: 1, maxLength: 128}
              manifest_count: {type: integer, minimum: 1, maximum: 25}
              project_path: {type: [string, "null"], maxLength: 2048}
              branch_name: {type: [string, "null"], maxLength: 512}
              branch_args:
                type: object
                additionalProperties: false
                required: [project, prefix, ticket_key, summary, source_ref, dry_run]
                properties:
                  project: {type: [integer, string], minLength: 1, maxLength: 2048}
                  prefix: {type: string, minLength: 1, maxLength: 512}
                  ticket_key: {type: string, minLength: 1, maxLength: 128}
                  summary: {type: string, minLength: 1, maxLength: 2048}
                  source_ref: {type: string, minLength: 1, maxLength: 512}
                  dry_run: {type: boolean, const: false}
              commit_args:
                type: object
                additionalProperties: false
                required: [project, branch, commit_message, actions, dry_run]
                properties:
                  project: {type: [integer, string], minLength: 1, maxLength: 2048}
                  branch: {type: string, minLength: 1, maxLength: 512}
                  commit_message: {type: string, minLength: 1, maxLength: 4096}
                  actions:
                    type: array
                    minItems: 1
                    maxItems: 10
                    items:
                      type: object
                      additionalProperties: false
                      required: [action, file_path, content]
                      properties:
                        action: {type: string, enum: [create, update, delete]}
                        file_path: {type: string, minLength: 1, maxLength: 4096}
                        content: {type: string, maxLength: 16384}
                        last_commit_id: {type: string, minLength: 1, maxLength: 512}
                  dry_run: {type: boolean, const: false}
              merge_request_args:
                type: object
                additionalProperties: false
                required: [project, source_branch, target_branch, title, description, remove_source_branch, squash, dry_run]
                properties:
                  project: {type: [integer, string], minLength: 1, maxLength: 2048}
                  source_branch: {type: string, minLength: 1, maxLength: 512}
                  target_branch: {type: string, minLength: 1, maxLength: 512}
                  title: {type: string, minLength: 1, maxLength: 1024}
                  description: {type: string, maxLength: 16384}
                  remove_source_branch: {type: boolean}
                  squash: {type: boolean}
                  dry_run: {type: boolean, const: false}
              jira_comment_args:
                type: object
                additionalProperties: false
                required: [key, body, dry_run]
                properties:
                  key: {type: string, minLength: 3, maxLength: 128}
                  body: {type: string, minLength: 1, maxLength: 32000}
                  dry_run: {type: boolean, const: false}
              should_create_branch: {type: integer, enum: [0, 1]}
              should_commit: {type: integer, enum: [0, 1]}
              should_create_merge_request: {type: integer, enum: [0, 1]}
              should_comment_jira: {type: integer, enum: [0, 1]}
              branch_intent_digest: {type: string, minLength: 64, maxLength: 64, pattern: '^[0-9a-f]{64}$'}
              commit_intent_digest: {type: string, minLength: 64, maxLength: 64, pattern: '^[0-9a-f]{64}$'}
              merge_request_intent_digest: {type: string, minLength: 64, maxLength: 64, pattern: '^[0-9a-f]{64}$'}
              jira_comment_intent_digest: {type: string, minLength: 64, maxLength: 64, pattern: '^[0-9a-f]{64}$'}
              terminal_outcome: {type: string, enum: [fixed, not_found, permission, needs_info, manual_review, not_a_code_fix, safely_skipped]}
              warnings: {type: array, maxItems: 25, items: {type: string, maxLength: 1024}}

        - id: approve-branch
          depends_on: [prepare-writes]
          when: "$prepare-writes.output.should_create_branch == 1"
          approval:
            message: >
              Approve only this current branch operation. Enabled flag:
              $prepare-writes.output.should_create_branch; exact connector
              arguments: $prepare-writes.output.branch_args; intent digest:
              $prepare-writes.output.branch_intent_digest; this approval binds
              only this run, iteration, operation, current attempt, and payload.
            capture_response: true

        - id: create-branch
          depends_on: [approve-branch, prepare-writes]
          when: "$prepare-writes.output.should_create_branch == 1"
          prompt: >
            The approved exact payload is $prepare-writes.output.branch_args
            with intent digest $prepare-writes.output.branch_intent_digest; if
            $prepare-writes.output.should_create_branch is zero, call no tool
            and return safely_skipped. Otherwise call gitlab_create_branch
            exactly once using that argument object unchanged. Request the
            connector host current-action approval. Never reconstruct fields.
            Ambiguous results require read-only reconciliation and failure.
          allowed_tools: [gitlab_create_branch]
          retry: {max_attempts: 1}
          output_format: &write_result
            type: object
            additionalProperties: false
            required: [ticket_key, operation, status, object_id, web_url, warnings, attention_needed, reconciliation_status]
            properties:
              ticket_key: {type: string, minLength: 1, maxLength: 128}
              operation: {type: string, enum: [create_branch, commit_changes, create_merge_request, add_jira_comment]}
              status: {type: string, const: success}
              object_id: {type: [string, "null"], maxLength: 512}
              web_url: {type: [string, "null"], maxLength: 4096}
              warnings: {type: array, maxItems: 25, items: {type: string, maxLength: 1024}}
              attention_needed: {type: boolean}
              reconciliation_status: {type: string, enum: [not_required, confirmed, failed_closed]}

        - id: approve-commit
          depends_on: [create-branch, prepare-writes]
          when: "$prepare-writes.output.should_commit == 1 && $create-branch.output.status == 'success'"
          approval:
            message: >
              Approve only this current commit operation. Enabled flag:
              $prepare-writes.output.should_commit; exact connector arguments,
              including bounded action content and any last_commit_id:
              $prepare-writes.output.commit_args; intent digest:
              $prepare-writes.output.commit_intent_digest; this approval binds
              only this run, iteration, operation, current attempt, and payload.
            capture_response: true

        - id: commit-changes
          depends_on: [approve-commit, prepare-writes, create-branch]
          when: "$prepare-writes.output.should_commit == 1 && $create-branch.output.status == 'success'"
          prompt: >
            The approved exact payload is $prepare-writes.output.commit_args
            with intent digest $prepare-writes.output.commit_intent_digest; if
            $prepare-writes.output.should_commit is zero, call no tool and
            return safely_skipped. Otherwise call gitlab_commit_changes exactly
            once using that argument object unchanged. Request connector host
            current-action approval. Never recreate content or last_commit_id.
            Ambiguous results require read-only reconciliation and failure.
          allowed_tools: [gitlab_commit_changes]
          retry: {max_attempts: 1}
          output_format: *write_result

        - id: approve-merge-request
          depends_on: [commit-changes, prepare-writes]
          when: "$prepare-writes.output.should_create_merge_request == 1 && $commit-changes.output.status == 'success'"
          approval:
            message: >
              Approve only this current merge-request operation. Enabled flag:
              $prepare-writes.output.should_create_merge_request; exact
              connector arguments: $prepare-writes.output.merge_request_args;
              Intent digest:
              $prepare-writes.output.merge_request_intent_digest; this approval
              binds only this run, iteration, operation, current attempt, and payload.
            capture_response: true

        - id: create-merge-request
          depends_on: [approve-merge-request, prepare-writes, commit-changes]
          when: "$prepare-writes.output.should_create_merge_request == 1 && $commit-changes.output.status == 'success'"
          prompt: >
            The approved exact payload is
            $prepare-writes.output.merge_request_args with intent digest
            $prepare-writes.output.merge_request_intent_digest; if
            $prepare-writes.output.should_create_merge_request is zero, call no
            tool and return safely_skipped. Otherwise call
            gitlab_create_merge_request exactly once using that object
            unchanged and request connector host current-action approval.
            Ambiguous results require read-only reconciliation and failure.
          allowed_tools: [gitlab_create_merge_request]
          retry: {max_attempts: 1}
          output_format: *write_result

        - id: review-merge-request
          depends_on: [create-merge-request, prepare-writes]
          when: "$prepare-writes.output.should_create_merge_request == 1 && $create-merge-request.output.status == 'success'"
          prompt: >
            If merge-request creation succeeded, call
            gitlab_read_merge_request once to corroborate its exact identity.
            Otherwise call no tool and return safely_skipped. Never write.
          allowed_tools: [gitlab_read_merge_request]
          retry: {max_attempts: 1}
          output_format:
            type: object
            additionalProperties: false
            required: [ticket_key, operation, status, merge_request_id, merge_request_url, warnings, attention_needed, reconciliation_status]
            properties:
              ticket_key: {type: string, minLength: 1, maxLength: 128}
              operation: {type: string, const: review_merge_request}
              status: {type: string, const: success}
              merge_request_id: {type: [string, "null"], maxLength: 512}
              merge_request_url: {type: [string, "null"], maxLength: 4096}
              warnings: {type: array, maxItems: 25, items: {type: string, maxLength: 1024}}
              attention_needed: {type: boolean}
              reconciliation_status: {type: string, enum: [not_required, confirmed, failed_closed]}

        - id: approve-jira-comment
          depends_on: [review-merge-request, prepare-writes]
          when: "$prepare-writes.output.should_comment_jira == 1 && $review-merge-request.output.status == 'success'"
          approval:
            message: >
              Approve only this current Jira comment operation. Enabled flag:
              $prepare-writes.output.should_comment_jira; exact connector
              arguments: $prepare-writes.output.jira_comment_args; intent
              digest: $prepare-writes.output.jira_comment_intent_digest; this
              approval binds only this run, iteration, operation, current attempt, and payload.
            capture_response: true

        - id: update-jira
          depends_on: [approve-jira-comment, prepare-writes, review-merge-request]
          when: "$prepare-writes.output.should_comment_jira == 1 && $review-merge-request.output.status == 'success'"
          prompt: >
            The approved exact payload is
            $prepare-writes.output.jira_comment_args with intent digest
            $prepare-writes.output.jira_comment_intent_digest; if
            $prepare-writes.output.should_comment_jira is zero, call no tool
            and return safely_skipped. Otherwise call jira_add_comment exactly
            once using that object unchanged and request connector host
            current-action approval. Ambiguous results require read-only
            reconciliation and failure.
          allowed_tools: [jira_add_comment]
          retry: {max_attempts: 1}
          output_format: *write_result

        - id: publish-ticket-record
          depends_on: [create-branch, commit-changes, create-merge-request, review-merge-request, update-jira, prepare-writes]
          trigger_rule: none_failed_min_one_success
          script: |
            const plan = $prepare-writes.output;
            const predecessors = JSON.parse(await Bun.file(process.env.HERMES_WORKFLOW_PREDECESSORS_FILE).text());
            const result = (nodeId, enabled, operation) => {
              const entry = predecessors[nodeId];
              if (!enabled) {
                if (entry?.state === "succeeded") throw new Error(`unexpected ${operation} result`);
                return null;
              }
              const value = entry?.state === "succeeded" ? entry.output : null;
              if (!value || value.ticket_key !== plan.ticket_key || value.operation !== operation || value.status !== "success" || value.reconciliation_status === "failed_closed") throw new Error(`missing or uncorroborated ${operation} result`);
              return value;
            };
            const branch = result("create-branch", plan.should_create_branch, "create_branch");
            const commit = result("commit-changes", plan.should_commit, "commit_changes");
            const mergeRequest = result("create-merge-request", plan.should_create_merge_request, "create_merge_request");
            const review = result("review-merge-request", plan.should_create_merge_request, "review_merge_request");
            const jira = result("update-jira", plan.should_comment_jira, "add_jira_comment");
            if (branch && (!branch.object_id || branch.object_id !== plan.branch_name)) throw new Error("branch identity mismatch");
            if (commit && !commit.object_id) throw new Error("commit identity missing");
            if (mergeRequest && (!mergeRequest.object_id || !mergeRequest.web_url)) throw new Error("merge request write identity missing");
            if (review && (!review.merge_request_id || !review.merge_request_url)) throw new Error("merge request review identity missing");
            if (mergeRequest && review && (mergeRequest.object_id !== review.merge_request_id || mergeRequest.web_url !== review.merge_request_url)) throw new Error("merge request evidence mismatch");
            if (jira && !jira.object_id) throw new Error("Jira comment identity missing");
            const present = [branch, commit, mergeRequest, review, jira].filter(Boolean);
            const warnings = [plan, ...present].flatMap((value) => value.warnings || []).slice(0, 50);
            const attention = plan.terminal_outcome === "permission" || plan.terminal_outcome === "manual_review" || present.some((value) => value.attention_needed);
            const reconciliation = present.some((value) => value.reconciliation_status === "confirmed") ? "confirmed" : "not_required";
            console.log(JSON.stringify({ticket_key: plan.ticket_key, outcome: plan.terminal_outcome, status: "terminal", project_path: plan.project_path, branch_name: branch?.object_id || null, commit_id: commit?.object_id || null, merge_request_url: review?.merge_request_url || null, jira_comment_id: jira?.object_id || null, warnings, attention_needed: attention, reconciliation_status: reconciliation}));
          runtime: bun
          artifacts: false
          output_type: JiraDefectTicketRecord
          output_format: &ticket_record
            type: object
            additionalProperties: false
            required: [ticket_key, outcome, status, project_path, branch_name, commit_id, merge_request_url, jira_comment_id, warnings, attention_needed, reconciliation_status]
            properties:
              ticket_key: {type: string, minLength: 1, maxLength: 128}
              outcome: {type: string, enum: [fixed, not_found, permission, needs_info, manual_review, not_a_code_fix, safely_skipped]}
              status: {type: string, const: terminal}
              project_path: {type: [string, "null"], maxLength: 2048}
              branch_name: {type: [string, "null"], maxLength: 512}
              commit_id: {type: [string, "null"], maxLength: 512}
              merge_request_url: {type: [string, "null"], maxLength: 4096}
              jira_comment_id: {type: [string, "null"], maxLength: 512}
              warnings: {type: array, maxItems: 50, items: {type: string, maxLength: 1024}}
              attention_needed: {type: boolean}
              reconciliation_status: {type: string, enum: [not_required, confirmed, failed_closed]}

        - id: record-cumulative-state
          depends_on: [publish-ticket-record, select-ticket]
          script: |
            const current = $publish-ticket-record.output;
            const selected = $select-ticket.output;
            const previous = [$LOOP_PREV.record-cumulative-state.output];
            const prior = previous.length ? previous[0] : {manifest_count: selected.manifest_count, completed_count: 0, records: [], counts: {fixed: 0, not_found: 0, permission: 0, needs_info: 0, manual_review: 0, not_a_code_fix: 0, safely_skipped: 0}, warnings: []};
            if (prior.manifest_count !== selected.manifest_count || prior.completed_count !== selected.index || prior.records.length !== selected.index) throw new Error("cumulative count mismatch");
            if (current.ticket_key !== selected.ticket_key || prior.records.some((row) => row.ticket_key === current.ticket_key)) throw new Error("duplicate or wrong terminal key");
            const records = [...prior.records, current];
            const counts = {...prior.counts, [current.outcome]: prior.counts[current.outcome] + 1};
            if (Object.values(counts).reduce((sum, count) => sum + count, 0) !== records.length) throw new Error("terminal aggregate mismatch");
            const completion_marker = records.length === selected.manifest_count ? "<promise>BATCH_COMPLETE</promise>" : "";
            console.log(JSON.stringify({manifest_count: selected.manifest_count, completed_count: records.length, records, counts, warnings: records.flatMap((row) => row.warnings).slice(0, 50), completion_marker}));
          runtime: bun
          artifacts: false
          output_type: JiraDefectAggregateJson
          output_format:
            type: object
            additionalProperties: false
            required: [manifest_count, completed_count, records, counts, warnings, completion_marker]
            properties:
              manifest_count: {type: integer, minimum: 1, maximum: 25}
              completed_count: {type: integer, minimum: 1, maximum: 25}
              records:
                type: array
                minItems: 1
                maxItems: 25
                uniqueItems: true
                items: *ticket_record
              counts: &outcome_counts
                type: object
                additionalProperties: false
                required: [fixed, not_found, permission, needs_info, manual_review, not_a_code_fix, safely_skipped]
                properties:
                  fixed: {type: integer, minimum: 0, maximum: 25}
                  not_found: {type: integer, minimum: 0, maximum: 25}
                  permission: {type: integer, minimum: 0, maximum: 25}
                  needs_info: {type: integer, minimum: 0, maximum: 25}
                  manual_review: {type: integer, minimum: 0, maximum: 25}
                  not_a_code_fix: {type: integer, minimum: 0, maximum: 25}
                  safely_skipped: {type: integer, minimum: 0, maximum: 25}
              warnings: {type: array, maxItems: 50, items: {type: string, maxLength: 1024}}
              completion_marker: {type: string, enum: ["", "<promise>BATCH_COMPLETE</promise>"]}

  - id: publish-empty-json
    depends_on: [fetch-ticket-manifest]
    when: "$fetch-ticket-manifest.output.count == 0"
    script: |
      console.log(JSON.stringify({manifest_count: 0, completed_count: 0, records: [], counts: {fixed: 0, not_found: 0, permission: 0, needs_info: 0, manual_review: 0, not_a_code_fix: 0, safely_skipped: 0}, warnings: []}));
    runtime: bun
    artifacts: false
    output_type: JiraDefectAggregateJson
    output_format: &aggregate_json
      type: object
      additionalProperties: false
      required: [manifest_count, completed_count, records, counts, warnings]
      properties:
        manifest_count: {type: integer, minimum: 0, maximum: 25}
        completed_count: {type: integer, minimum: 0, maximum: 25}
        records:
          type: array
          maxItems: 25
          uniqueItems: true
          items: *ticket_record
        counts: *outcome_counts
        warnings: {type: array, maxItems: 50, items: {type: string, maxLength: 1024}}

  - id: publish-empty-markdown
    depends_on: [publish-empty-json, fetch-ticket-manifest]
    when: "$fetch-ticket-manifest.output.count == 0"
    script: |
      console.log("# Jira Defect Loop\n\nThe immutable manifest was empty. No ticket writes were attempted.");
    runtime: bun
    artifacts: false
    output_type: JiraDefectAggregateMarkdown

  - id: publish-aggregate-json
    depends_on: [process-ticket-manifest, fetch-ticket-manifest]
    when: "$fetch-ticket-manifest.output.count > 0"
    script: |
      const manifest = $fetch-ticket-manifest.output;
      const state = $process-ticket-manifest.output;
      const {completion_marker, ...published} = state;
      const keys = manifest.tickets.map((ticket) => ticket.key);
      const recordKeys = state.records.map((record) => record.ticket_key);
      if (completion_marker !== "" || manifest.count !== keys.length || state.manifest_count !== keys.length || state.completed_count !== keys.length || JSON.stringify(keys) !== JSON.stringify(recordKeys) || new Set(recordKeys).size !== recordKeys.length) throw new Error("final aggregate does not match immutable manifest");
      const countTotal = Object.values(state.counts).reduce((sum, count) => sum + count, 0);
      if (countTotal !== state.completed_count) throw new Error("final outcome counts do not reconcile");
      console.log(JSON.stringify(published));
    runtime: bun
    artifacts: false
    output_type: JiraDefectAggregateJson
    output_format: *aggregate_json

  - id: publish-aggregate-markdown
    depends_on: [publish-aggregate-json, fetch-ticket-manifest]
    when: "$fetch-ticket-manifest.output.count > 0"
    script: |
      const state = $publish-aggregate-json.output;
      const lines = ["# Jira Defect Loop", "", `Completed ${state.completed_count} of ${state.manifest_count} immutable manifest tickets.`, ""];
      for (const record of state.records) {
        lines.push(`- **${record.ticket_key}**: ${record.outcome}${record.attention_needed ? " (attention needed)" : ""}`);
        if (record.project_path) lines.push(`  - Project: ${record.project_path}`);
        if (record.branch_name) lines.push(`  - Branch: ${record.branch_name}`);
        if (record.commit_id) lines.push(`  - Commit: ${record.commit_id}`);
        if (record.merge_request_url) lines.push(`  - Merge request: ${record.merge_request_url}`);
        if (record.jira_comment_id) lines.push(`  - Jira comment: ${record.jira_comment_id}`);
        lines.push(`  - Reconciliation: ${record.reconciliation_status}`);
        for (const warning of record.warnings) lines.push(`  - Warning: ${warning}`);
      }
      console.log(lines.join("\n"));
    runtime: bun
    artifacts: false
    output_type: JiraDefectAggregateMarkdown
